import{_ as d,c as a,o as e,ag as r}from"./chunks/framework.C86mscM5.js";const N=JSON.parse('{"title":"DNS (Domain Name System)","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/network/DNS.md","filePath":"fundamentals/network/DNS.md","lastUpdated":1788689791000}'),n={name:"fundamentals/network/DNS.md"};function o(s,t,S,m,i,l){return e(),a("div",null,t[0]||(t[0]=[r('<h1 id="dns-domain-name-system" tabindex="-1">DNS (Domain Name System) <a class="header-anchor" href="#dns-domain-name-system" aria-label="Permalink to &quot;DNS (Domain Name System)&quot;">​</a></h1><h2 id="dns-记录类型" tabindex="-1">DNS 记录类型 <a class="header-anchor" href="#dns-记录类型" aria-label="Permalink to &quot;DNS 记录类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>记录类型</th><th>使用目的</th></tr></thead><tbody><tr><td>A 记录</td><td>将域名指向一个 IPv4 地址。</td></tr><tr><td>AAAA 记录</td><td>将域名指向一个 IPv6 地址。</td></tr><tr><td>CNAME 记录</td><td>将域名指向另一个域名，再由另一个域名提供 IP 地址。</td></tr><tr><td>MX 记录</td><td>设置邮箱，让邮箱能收到邮件。</td></tr><tr><td>TXT 记录</td><td>对域名进行标识和说明，绝大多数的 TXT 记录是用来做 SPF 记录（反垃圾邮件）。</td></tr><tr><td>NS 记录</td><td>将子域名交给其他 DNS 服务商解析。</td></tr><tr><td>CAA 记录</td><td>授权指定 CA 机构为域名签发 SSL 证书，以防止 SSL 证书错误签发。</td></tr><tr><td>SVCB 记录</td><td>用来说明服务的 IP 地址，ECH 公钥以及其他建立连接所需的信息，通过一次 DNS 查询来加速通信连接过程。</td></tr><tr><td>HTTPS 记录</td><td>HTTPS 记录是一类特殊的 SVCB 记录，说明 HTTPS 建联所需的信息。</td></tr><tr><td>隐、显性 URL 记录</td><td>将一个域名指向另外一个已经存在的站点。</td></tr></tbody></table>',3)]))}const h=d(n,[["render",o]]);export{N as __pageData,h as default};
